#include <cstdio>
#include <cstring>
#include <algorithm>
const int MAXN = 50 + 10;
const int MOD = 1e9 + 7;
typedef long long LL;

LL n;
int k;

inline int add(int x) { return x >= MOD ? x - MOD : x; }
inline int sub(int x) { return x < 0 ? x + MOD : x; }
inline int mul(int x, int y) { return (LL)x * y % MOD; }

struct Mat {
    int a[MAXN][MAXN];
    int n;
    void init() { memset(a, 0, sizeof a); }
    void set() { init(); for (int i = 1; i <= n; ++i) a[i][i] = 1; }
    Mat operator*(const Mat &rhs) const {
        Mat res;
        res.n = n;
        res.init();
        for (int i = 1; i <= n; ++i)
            for (int j = 1; j <= n; ++j) {
                LL s = 0;
                for (int k = 1; k <= n; ++k)
                    s += (LL)a[i][k] * rhs.a[k][j];
                res.a[i][j] = s % MOD;
            }
        return res;
    }
};

Mat f[80][MAXN], sump[80][MAXN], sums[80][MAXN];

int main() {
    scanf("%lld%d", &n, &k);
    int num[80], cnt = 0;
    LL tn = n;
    while (tn) { num[++cnt] = tn % k; tn /= k; }
    for (int i = 0; i < k; ++i) {
        f[0][i].n = k+1;
        f[0][i].set();
        for (int j = 1; j <= k+1; ++j) f[0][i].a[i+1][j] = 1;
    }
    // Compute prefix and suffix products in a different order
    for (int i = 0; i < k; ++i) {
        if (i == 0) sump[0][i] = f[0][i];
        else sump[0][i] = f[0][i] * sump[0][i-1];
    }
    for (int i = k-1; i >= 0; --i) {
        if (i == k-1) sums[0][i] = f[0][i];
        else sums[0][i] = sums[0][i+1] * f[0][i];
    }
    for (int i = 1; i < cnt; ++i) {
        for (int j = 0; j < k; ++j) {
            if (j == 0) f[i][j] = sums[i-1][j];
            else f[i][j] = sump[i-1][j-1] * sums[i-1][j];
        }
        for (int j = 0; j < k; ++j) {
            if (j == 0) sump[i][j] = f[i][j];
            else sump[i][j] = f[i][j] * sump[i][j-1];
        }
        for (int j = k-1; j >= 0; --j) {
            if (j == k-1) sums[i][j] = f[i][j];
            else sums[i][j] = sums[i][j+1] * f[i][j];
        }
    }
    Mat ans;
    ans.n = k+1;
    ans.set();
    int sum = 0;
    for (int i = cnt; i >= 1; --i) {
        for (int j = 0; j < num[i]; ++j) ans = f[i-1][(sum+j)%k] * ans;
        sum = (sum + num[i]) % k;
    }
    int res = 0;
    for (int i = 1; i <= k+1; ++i) res = add(res + ans.a[i][k+1]);
    printf("%d\n", res);
    return 0;
}
